css:
&.slide.tpl {
& { padding:80px 100px; display:grid; grid-template-columns:490px minmax(0,1fr); gap:70px; align-items:stretch; }
.bf-image { margin:0; min-height:0; }
.bf-image img { width:100%; height:100%; object-fit:contain; border-radius:8px; }
.bf-content { display:flex; flex-direction:column; gap:24px; min-width:0; }
header p { color:var(--accent); font:20px var(--font-mono,var(--mono)); margin:0 0 12px; }
header h2 { font-size:65px; line-height:1.06; margin:0; text-wrap:balance; }
header div { font-size:30px; line-height:1.32; color:var(--ink); margin-top:22px; }
header :empty { display:none; }
ol { display:flex; flex:1; flex-direction:column; list-style:none; padding:0; margin:0; }
li { position:relative; padding:20px 0 20px 26px; border-bottom:1px solid var(--line); opacity:1!important; transform:none!important; }
li b { display:block; font-size:34px; line-height:1.14; font-weight:650; color:var(--ink); }
li span { display:block; font-size:29px; line-height:1.3; margin-top:10px; opacity:0; }
li.in span,li:not([data-step]) span { opacity:1; }
li.step-current { background:color-mix(in srgb,var(--accent) 10%,transparent); }
li.step-current::before { content:""; position:absolute; left:0; top:18px; bottom:18px; width:4px; background:var(--accent); }
li.step-current b { color:var(--accent); }
li.step-past span { opacity:.82; }
&:has([data-template-end].in),&:has([data-template-end]:not([data-step])) { li { background:transparent; } li::before { display:none; } li b { color:var(--ink); } li span { opacity:1; } }
[data-template-end] { position:absolute; width:0; height:0; overflow:hidden; }
&:has(.bf-image img[src=""]) { grid-template-columns:1fr; } &:has(.bf-image img[src=""]) .bf-image { display:none; }
&:has(li:nth-child(4)) { li { padding-top:14px; padding-bottom:14px; } li span { font-size:28px; } }

}
